{"command":"cat <<'EOF' > test_openssl_rust.rs
#[link(name = "crypto")]
extern "C" {
    fn OpenSSL_version(t: i32) -> *const i8;
}
fn main() {
    unsafe {
        let s = OpenSSL_version(0);
        let s = std::ffi::CStr::from_ptr(s).to_str().unwrap();
        println!("OpenSSL version: {}", s);
    }
}
EOF
rustc test_openssl_rust.rs -o test_openssl_rust
./test_openssl_rust"}

